    HealthIndicatorType = apps.get_model("health_packages", "HealthIndicatorType")
    diet_keys = {"calories", "carbs", "protein", "fat"}
    diet_type_ids = set(
        HealthIndicatorType.objects.filter(system_key__in=diet_keys).values_list("id", flat=True)
    )
    tz = timezone.get_current_timezone()

    qs = HealthIndicator.objects.only("id", "date", "indicator_type_id").order_by("id")
    batch = []
    BATCH_SIZE = 500
    for ind in qs.iterator(chunk_size=BATCH_SIZE):
        if ind.date is None:
            continue
        naive = datetime.combine(ind.date, time(12, 0))
        ind.recorded_at = timezone.make_aware(naive, tz)
        ind.source = "diet_ai" if ind.indicator_type_id in diet_type_ids else "manual"
        batch.append(ind)
        if len(batch) >= BATCH_SIZE:
            HealthIndicator.objects.bulk_update(batch, ["recorded_at", "source"])
            batch.clear()
    if batch:
        HealthIndicator.objects.bulk_update(batch, ["recorded_at", "source"])


